const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const bar=(value,total,label)=>`<progress max="${total||1}" value="${value}" aria-label="${esc(label)}"></progress>`;
const accuracy=(a,label)=>`<div class="mastery-stat"><span>${esc(label)}</span><strong>${a.percent===null?'—':a.percent+'%'}</strong><small>${a.total?`${a.correct} of ${a.total} answers correct`:'Answer some questions to build your picture.'}</small></div>`;
export function dashboardHTML(s){const review=s.topics.filter(t=>t.due);return `<section class="mastery-dashboard"><span class="eyebrow">${esc(s.subject)} · MY PROGRESS</span><h2>Your mastery journey</h2><p class="mastery-scope">${esc(s.scope)}</p><div class="mastery-overview"><div class="mastery-ring" style="--mastery:${s.percent}%" role="img" aria-label="${s.completed} of ${s.total} lessons completed, ${s.percent} percent"><div><strong>${s.percent}%</strong><span>completed</span></div></div><div class="mastery-counts"><div><strong>${s.completed}</strong><span>lessons completed</span></div><div><strong>${s.remaining}</strong><span>left to complete</span></div><div><strong>${s.inProgress}</strong><span>in progress</span></div></div></div><p class="mastery-note">${esc(s.scopeNote)}</p><section class="mastery-section"><h3>Every step counts</h3><div class="mastery-stages">${['Discover','Investigate','Practise','Check passed'].map((name,i)=>`<div><span>${i+1}. ${name}</span>${bar(s.stages[i],s.total,name)}<small>${s.stages[i]} / ${s.total} lessons</small></div>`).join('')}</div><p class="mastery-note">Complete all four steps to complete a lesson. Passing Check means at least 80%.</p></section><section class="mastery-section"><h3>How you’re doing</h3><div class="mastery-performance">${accuracy(s.practice,s.practiceLabel)}${accuracy(s.check,'Latest lesson-check answers')}<div class="mastery-stat"><span>Gaps to address</span><strong>${s.gaps.length}</strong><small>${s.gaps.length?'Concepts or skills flagged for another look.':'No gaps flagged yet. New answers will help identify them.'}</small></div></div><p class="mastery-note">Check accuracy includes recorded answers in your latest lesson runs, including unfinished runs. This is learning progress, not a predicted GCSE grade.</p></section><div class="mastery-actions"><section class="mastery-section"><h3>Work on these next</h3>${s.gaps.length?`<div class="mastery-list">${s.gaps.map(g=>`<button class="mastery-action" data-progress-lesson="${esc(g.lessonId)}"><span><b>${esc(g.label)}</b><small>${esc(s.topics.find(t=>t.id===g.topicId)?.title||'')}</small></span><span>Revisit →</span></button>`).join('')}</div>`:'<p>No answers need another look yet. Start or continue a lesson to find your next step.</p>'}</section><section class="mastery-section"><h3>Topics to revisit</h3>${review.length?`<p>${s.due.length} ${s.due.length===1?'concept or skill is':'concepts or skills are'} due for recall or need more practice.</p><div class="mastery-list">${review.map(t=>`<button class="mastery-action" data-progress-review="${esc(t.id)}"><span><b>${esc(t.discipline?t.discipline+' · '+t.title:t.title)}</b><small>${t.due} due or flagged</small></span><span>Review →</span></button>`).join('')}</div>`:'<p>Nothing due for recall yet. Completed learning returns here when it is time to revisit it.</p>'}</section></div><section class="mastery-section"><h3>Your topics</h3><div class="mastery-topics">${s.topics.map(t=>`<details class="mastery-topic"><summary><span><b>${esc(t.discipline?t.discipline+' · '+t.title:t.title)}</b><small>${t.completed} completed · ${t.total-t.completed} remaining${t.gaps?' · '+t.gaps+' gaps':''}</small></span>${bar(t.completed,t.total,t.title+' lesson completion')}<span aria-hidden="true">⌄</span></summary><div class="mastery-lesson-list">${t.lessons.map(l=>{const n=l.stages.filter(Boolean).length;return `<button class="mastery-action" data-progress-lesson="${esc(l.id)}" data-progress-stage="${n===4?0:l.stages.findIndex(v=>!v)}"><span>${esc(l.title)}<small>${n===4?'Completed':l.started?`${n} of 4 steps complete · Next: ${['Discover','Investigate','Practise','Check'][l.stages.findIndex(v=>!v)]}`:'Not started'}</small></span><span aria-hidden="true">→</span></button>`;}).join('')}</div></details>`).join('')}</div></section><p class="mastery-note">Progress is saved in this browser on this device. Reviews help keep completed learning fresh.</p></section>`;}
